package com.municipio.base_conocimiento.auditoria.service;
import com.municipio.base_conocimiento.auditoria.dto.EventoAuditoriaResponse;import com.municipio.base_conocimiento.auditoria.entity.EventoAuditoria;import com.municipio.base_conocimiento.auditoria.repository.EventoAuditoriaRepository;import java.util.List;import org.springframework.data.domain.Sort;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service public class AuditoriaService{private final EventoAuditoriaRepository repo;public AuditoriaService(EventoAuditoriaRepository repo){this.repo=repo;}@Transactional public void registrar(String usuario,String accion,String recurso,int codigo,String ip){repo.save(new EventoAuditoria(usuario,accion,recurso,codigo,ip));}@Transactional(readOnly=true) public List<EventoAuditoriaResponse> listar(){return repo.findAll(Sort.by(Sort.Direction.DESC,"ocurridoEn")).stream().limit(500).map(EventoAuditoriaResponse::de).toList();}}
